 useEffect(()=>{const read=()=>{const [page,id,tab]=window.location.hash.slice(1).split('/').map(decodeURIComponent);if(page)setRoute({page,id,tab});};read();window.addEventListener('hashchange',read);return()=>window.removeEventListener('hashchange',read)},[]);
 const load=useCallback(async()=>{setLoading(true);setError('');try{const res=await fetch('/api/records',{headers:workspaceIdRef.current?{'X-Workspace-Id':workspaceIdRef.current}:{}});const data:any=await res.json();if(res.status===401){setAuth(true);setDraft(null);setDraftError('');setRecords([]);setMembers([]);setWorkspace(null);workspaceIdRef.current=null;return}if(res.status===403){setRecords([]);setMembers([]);setWorkspace(null);workspaceIdRef.current=null;if(data.code==='no-workspace'){setNoAccess(true);return}}if(!res.ok)throw Error(data.error);setRecords(data.records);setUser(data.user);setWorkspace(data.workspace);setMembers(data.members);setWorkspaces(data.workspaces||[]);if(data.today)setToday(data.today);workspaceIdRef.current=data.workspace.id;setAuth(false)}catch(e){setError(e instanceof Error?e.message:'Chargement impossible.')}finally{setLoading(false)}},[]);
