 function open(type:Modal['type'],record?:RecordItem,defaults:{status?:Status;date?:string}={}){if(type==='task'&&!record){beginTask(defaults);return;}setModal({type,record,...defaults});setFormError('');setForm(record?{...Object.fromEntries(Object.entries(clean(record)).filter(([,v])=>typeof v==='string')),evergreen:record.evergreen?'true':''} as Form:{clientId:client?.id||clients.find(c=>!c.archived)?.id||'',name:'',status:defaults.status||'À faire',source:'Interne',due:defaults.date||today,assignee:'',description:'',language:'Français'});}
