 function Board(){return <div className="board">{statuses.map(s=><section className="board-column" key={s} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const t=tasks.find(t=>t.id===e.dataTransfer.getData('text/plain'));if(t)void update(t,{status:s})}}><header><Chip status={s}/><small>{filtered.filter(t=>t.status===s).length}</small><button aria-label={`Créer une tâche ${s}`} onClick={()=>open('task',undefined,{status:s})}><Plus size={16}/></button></header>{filtered.filter(t=>t.status===s).map(t=><article key={t.id} className="board-card" draggable={!showArchived&&!busy} onDragStart={e=>e.dataTransfer.setData('text/plain',t.id)}><small>{cname(t.clientId)}</small><button className="board-name" onClick={()=>navigate({page:'task',id:t.id})}>{t.name}</button>{link(t)&&<a className="file-pill" href={link(t)} target="_blank" rel="noopener noreferrer"><FileText size={13}/>Livrable<ArrowUpRight size={12}/></a>}<footer><Avatar name={t.assignee}/><span className={t.due&&t.due<today&&s!=='Validé'?'overdue':''}>{dateLabel(t.due)}</span><CourtChip task={t}/><button aria-label={`Modifier ${t.name}`} onClick={()=>open('task',t)}><MoreHorizontal size={17}/></button></footer>{s==='À valider'&&<small><Clock size={11}/> Tacite dans {Math.max(0,Math.round(hoursLeft(t,new Date())??0))} h</small>}{s==='Validé'&&t.publishedAt&&<small><CheckCircle2 size={11}/> Publié le {dateLabel(t.publishedAt.slice(0,10))}</small>}</article>)}<button className="add-row" onClick={()=>open('task',undefined,{status:s})}><Plus size={14}/>Nouvelle tâche</button></section>)}</div>}
 function Calendar({items,editorial=false,readOnly=false}:{items:RecordItem[];editorial?:boolean;readOnly?:boolean}){const start=new Date(month);start.setDate(1);start.setDate(start.getDate()-(start.getDay()+6)%7);if(calendarMode==='week'){start.setTime(month.getTime());start.setDate(start.getDate()-(start.getDay()+6)%7)}const days=Array.from({length:calendarMode==='week'?7:42},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});return <div className="calendar-wrap"><div className="calendar-toolbar"><button className="btn" onClick={()=>setMonth(new Date())}>Aujourd’hui</button><button className="icon-button" aria-label="Période précédente" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-(calendarMode==='month'?1:0),calendarMode==='month'?1:month.getDate()-7))}><ChevronLeft/></button><button className="icon-button" aria-label="Période suivante" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+(calendarMode==='month'?1:0),calendarMode==='month'?1:month.getDate()+7))}><ChevronRight/></button><h2>{month.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</h2><div className="grow"/><Tabs value={calendarMode} onValueChange={setCalendarMode}><TabsList><TabsTrigger value="month">Mois</TabsTrigger><TabsTrigger value="week">Semaine</TabsTrigger></TabsList></Tabs></div>{editorial&&<div className="channel-filters"><button className={!channel?'selected':''} onClick={()=>setChannel('')}>Tous les canaux</button>{channels.map(c=><button key={c} className={channel===c?'selected':''} onClick={()=>setChannel(c)}>{c}</button>)}</div>}<div className="calendar-grid"><div className="weekdays">{['Lun.','Mar.','Mer.','Jeu.','Ven.','Sam.','Dim.'].map(d=><span key={d}>{d}</span>)}</div><div className="calendar-days">{days.map(d=>{const key=dayKey(d);const events=items.filter(t=>t.due===key&&(!editorial||!!t.channel)&&(!channel||t.channel===channel));return <div className={`calendar-day ${d.getMonth()!==month.getMonth()?'outside':''}`} key={key}><header><span className={key===today?'today':''}>{d.getDate()}</span>{!readOnly&&<button aria-label={`Créer une tâche le ${key}`} onClick={()=>open('task',undefined,{date:key})}><Plus size={13}/></button>}</header>{events.map(t=><button key={t.id} className="calendar-event" onClick={()=>navigate({page:readOnly?'review':'task',id:t.id})}><strong>{t.name}</strong>{editorial&&<small>{t.time} · {t.channel}</small>}<Chip status={t.status}/></button>)}</div>})}</div></div></div>}
 function Toolbar(){return <div className="database-toolbar"><Tabs value={view} onValueChange={setView}><TabsList variant="line"><TabsTrigger value="table"><List size={16}/>Table</TabsTrigger><TabsTrigger value="board"><Columns3 size={16}/>Tableau</TabsTrigger><TabsTrigger value="calendar"><CalendarDays size={16}/>Calendrier</TabsTrigger></TabsList></Tabs><div className="toolbar-actions"><label className="search-input"><Search size={15}/><input aria-label="Rechercher une tâche" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Rechercher…"/></label><button className={`btn ghost ${filterOpen?'selected':''}`} onClick={()=>setFilterOpen(!filterOpen)}><Filter size={15}/>Filtrer{(statusFilter||assigneeFilter||courtFilter)&&<span className="filter-dot"/>}</button><Pick label="Trier les tâches" value={sort} onChange={setSort} items={[{value:'due',label:'Échéance'},{value:'name',label:'Nom'},{value:'status',label:'Statut'}]}/><button className="btn primary" onClick={()=>open('task')}><Plus size={16}/>Nouveau</button></div></div>}
 function TaskDatabase(){return <>{Toolbar()}{filterOpen&&<div className="filters"><span>Statut</span><Pick label="Filtrer par statut" value={statusFilter} onChange={setStatusFilter} items={[...statuses]}/><span>Assigné</span><Pick label="Filtrer par personne" value={assigneeFilter} onChange={setAssigneeFilter} items={assigneeOptions}/><span>Camp</span><Pick label="Filtrer par camp" value={courtFilter} onChange={setCourtFilter} items={[{value:'studio',label:'Studio'},{value:'client',label:'Client'},{value:'done',label:'Terminé'}]}/><button className="btn ghost" onClick={()=>{setStatusFilter('');setAssigneeFilter('');setCourtFilter('');setShowArchived(false)}}>Réinitialiser</button><button className={`btn ${showArchived?'selected':''}`} onClick={()=>setShowArchived(!showArchived)}><Archive size={14}/>{showArchived?'Archives affichées':'Afficher les archives'}</button></div>}{view==='table'?<div className="database-card">{TaskTable({items:filtered})}</div>:view==='board'?Board():<Calendar items={filtered}/>}</>}
 function Heading({emoji,title,subtitle,action}:{emoji:string;title:string;subtitle?:string;action?:React.ReactNode}){return <div className="page-heading"><span className="page-symbol" aria-hidden="true">{title==='Clients'?<Users size={22}/>:title==='Tâches'?<CheckSquare size={22}/>:<Folder size={22}/>}</span><div className="heading-line"><h1>{title}</h1>{action}</div>{subtitle&&<p>{subtitle}</p>}</div>}
 function HomePage(){
 const active=tasks.filter(t=>t.status!=='Validé'),mine=active.slice().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));
 const completed=tasks.filter(t=>t.status==='Validé'),firstName=user.name.includes('@')?'':user.name.split(' ')[0];
 return <div className="dashboard"><div className="dashboard-heading"><div><div className="eyebrow">VOTRE ESPACE DE TRAVAIL</div><h1>Bonjour{firstName?`, ${firstName}`:''}<span className="greeting-dot">.</span></h1><p>Les priorités du jour. Une vue d’ensemble du studio.</p></div><div className="dashboard-actions"><span className="date-tag"><CalendarDays size={15}/>{new Date().toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'})}</span><button className="btn primary" onClick={()=>open('task')}><Plus size={17}/>Nouvelle tâche</button></div></div>
 <div className="metric-grid">{[['Tâches actives',active.length,CheckSquare,'À faire et en cours de livraison'],['À valider',reviewTasks.length,Send,'Dans la file de validation'],['En retard',late.length,Clock,'À traiter en priorité'],['Tâches validées',completed.length,CheckCircle2,'Livrables approuvés']].map(([label,value,Icon,detail]:any)=><div className="metric-card" key={label}><div className="metric-label"><span>{label}</span><span className="metric-icon"><Icon size={18}/></span></div><strong>{String(value).padStart(2,'0')}</strong><small>{detail}</small></div>)}</div>
 {!records.length?<div className="onboarding-grid"><section className="onboarding-card"><span className="onboarding-icon"><Folder size={28}/></span><div className="eyebrow">UN NOUVEAU DÉPART</div><h2>Faites de la place<br/>à votre prochain projet.</h2><p>Un client, un brief, une équipe. Tout commence par votre première mission.</p><div className="inline"><button className="btn primary" onClick={()=>open('client')}><Plus size={16}/>Ajouter mon premier client</button><button disabled={busy} className="btn" onClick={demo}>Explorer la démo<ArrowUpRight size={16}/></button></div></section><section className="setup-card"><div className="section-head"><h2>Votre studio, organisé.</h2><span className="neutral-badge">3 étapes</span></div>{[['01','Ajoutez vos clients','Le brief et les informations au même endroit.'],['02','Structurez vos missions','Un sous-projet pour chaque objectif.'],['03','Faites avancer le travail','De la première idée à la validation.']].map(([n,title,text])=><div className="setup-step" key={n}><span>{n}</span><div><strong>{title}</strong><p>{text}</p></div></div>)}<div className="setup-footer"><Lock size={14}/>Votre espace est privé et prêt à accueillir vos projets.</div></section></div>:<div className="dashboard-grid"><section className="work-panel"><div className="section-head"><div><h2>Vos priorités<span className="neutral-badge">{active.length}</span></h2><p>Les prochaines tâches à faire avancer.</p></div><button className="btn" onClick={()=>navigate({page:'tasks'})}>Tout voir<ArrowUpRight size={14}/></button></div><TaskRows items={mine.slice(0,6)} compact/></section><section className="review-panel"><div className="section-head"><div><h2>À valider</h2><p>La prochaine étape est chez le client.</p></div><span className="review-count">{reviewTasks.length}</span></div>{reviewTasks.length?<div className="approval-list">{reviewTasks.slice(0,3).map(t=><button key={t.id} onClick={()=>navigate({page:'task',id:t.id})}><span className="approval-icon"><FileText size={19}/></span><span><small>{cname(t.clientId)}</small><strong>{t.name}</strong><span className="approval-date"><Clock size={12}/>{dateLabel(t.due)}</span></span><ArrowUpRight size={15}/></button>)}</div>:<Blank title="Tout est à jour" text="Aucun livrable en attente de validation."/>}<button className="review-all" onClick={()=>{navigate({page:'tasks'});setStatusFilter('À valider')}}>Voir la file de validation<ChevronRight size={16}/></button></section></div>}
 {(()=>{const alerts=records.filter(r=>r.kind==='event'&&r.audience!=='client'&&!r.read).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const requests=tasks.filter(t=>t.request&&t.status==='À faire');return (alerts.length||requests.length)?<section className="alerts-panel"><div className="section-head"><div><h2>À traiter<span className="neutral-badge">{alerts.length+requests.length}</span></h2><p>Horloges, verrou J−{flow.lockDays}, demandes clients.</p></div><button className="btn" onClick={()=>navigate({page:'flow'})}><Gauge size={14}/>Pilotage</button></div><div className="alerts-list">{requests.slice(0,3).map(t=><button key={t.id} onClick={()=>navigate({page:'task',id:t.id})}><span className="flow-event-icon"><Inbox size={15}/></span><span><small>Demande · {cname(t.clientId)}</small><strong>{t.name}{t.due?` · pour le ${dateLabel(t.due)}`:''}</strong></span><ChevronRight size={15}/></button>)}{alerts.slice(0,5).map(e=><button key={e.id} onClick={()=>{if(e.taskId)navigate({page:'task',id:e.taskId});void mutate({action:'mark-read',ids:[e.id]}).catch(()=>{})}}><span className={`flow-event-icon ${e.type}`}>{e.type==='lock'?<Lock size={15}/>:e.type==='reminder'?<Bell size={15}/>:e.type==='auto-approved'?<CheckCircle2 size={15}/>:<Clock size={15}/>}</span><span><small>{e.type==='auto-approved'?'Validation tacite':e.type==='reminder'?'Rappel':e.type==='sweep'?'Balayage J−1':e.type==='lock'?'Verrou J−7':e.type==='request'?'Demande':'Décision'} · {timeLabel(e.createdAt)}</small><strong>{e.name}</strong></span><ChevronRight size={15}/></button>)}</div></section>:null})()}
{!!records.length&&<section className="client-overview"><div className="section-head"><div><h2>Vos clients<span className="neutral-badge">{clients.filter(c=>!c.archived).length}</span></h2><p>Des relations qui font avancer le studio.</p></div><button className="text-link" onClick={()=>navigate({page:'clients'})}>Tous les clients<ArrowUpRight size={15}/></button></div><div className="client-strip">{clients.filter(c=>!c.archived).slice(0,4).map(c=><button key={c.id} onClick={()=>navigate({page:'client',id:c.id})}><span className="client-mark">{initials(c.name)}</span><span><strong>{c.name}</strong><small>{tasks.filter(t=>t.clientId===c.id).length} tâches actives</small></span><ArrowUpRight size={16}/></button>)}</div></section>}
 </div>;
 }
 function ClientsPage(){const list=clients.filter(c=>!!c.archived===showArchived&&c.name.toLowerCase().includes(query.toLowerCase()));return <><Heading emoji="🗂️" title="Clients" subtitle={`${clients.filter(c=>!c.archived).length} clients actifs — chaque relation, au même endroit.`}/><div className="client-toolbar"><label className="search-input"><Search size={16}/><input placeholder="Rechercher un client…" aria-label="Rechercher un client" value={query} onChange={e=>setQuery(e.target.value)}/></label><div className="grow"/><button className="btn primary" onClick={()=>open('client')}><Plus size={16}/>Nouveau client</button></div><div className="clients-grid">{list.map(c=>{const ts=tasks.filter(t=>t.clientId===c.id);return <button className="client-card" key={c.id} onClick={()=>navigate({page:'client',id:c.id})}><header><span className="client-mark">{initials(c.name)}</span><ArrowUpRight size={18}/></header><h2>{c.name}</h2><p>{c.sector||'Secteur à renseigner'} · {c.city||'Ville à renseigner'}</p><div className="client-counts"><span><strong>{ts.length}</strong>Tâches</span><span><strong>{ts.filter(t=>t.status==='À valider').length}</strong>À valider</span><span><strong>{ts.filter(t=>t.status==='Validé').length}</strong>Validées</span></div><footer><Avatar name={ts[0]?.assignee||'Studio'}/><small>{c.demo?'Client fictif · démonstration':`Créé le ${dateLabel(c.createdAt.slice(0,10))}`}</small></footer></button>})}</div>{!list.length&&<Blank title={showArchived?'Aucun client archivé':'Aucun client'} text="Ajoutez votre premier client pour organiser son travail."/>}<button className="add-row" onClick={()=>setShowArchived(!showArchived)}><Archive size={16}/>{showArchived?'Afficher les clients actifs':`Archivés (${clients.filter(c=>c.archived).length})`}<ChevronRight size={14}/></button></>}
 function ClientPage(){if(!client)return <Blank title="Client introuvable"/>;const tab=route.tab||'overview',ps=projects.filter(p=>p.clientId===client.id&&!p.archived);return <><Heading emoji="📁" title={client.name} subtitle={`${client.sector||'Client'} · ${client.city||''}${client.archived?' · Archivé':''}`} action={<button className="btn" onClick={()=>open('client',client)}>Modifier la fiche</button>}/><Tabs value={tab} onValueChange={tab=>navigate({page:'client',id:client.id,tab})}><TabsList variant="line" className="client-tabs"><TabsTrigger value="overview">Aperçu</TabsTrigger><TabsTrigger value="projects">Sous-projets <small>{ps.length}</small></TabsTrigger><TabsTrigger value="tasks">Tâches</TabsTrigger><TabsTrigger value="editorial">Plan éditorial</TabsTrigger></TabsList></Tabs>{tab==='overview'?<div className="detail-split"><article><div className="section-head"><h2>Brief</h2></div><p className="document-copy">{client.description||'Aucun brief pour le moment. Modifiez la fiche pour préciser les objectifs et la direction de la marque.'}</p><div className="section-head second"><h2>Liens utiles</h2></div>{[['Dossier partagé',client.drive],['Contrat',client.contract]].map(([label,url])=><div className="link-row" key={label}><LinkIcon size={16}/>{url?<a href={safeLink(url)} target="_blank" rel="noopener noreferrer">{label}<ArrowUpRight size={14}/></a>:<span>{label} · Aucun lien renseigné</span>}</div>)}<div className="section-head second"><h2>Sous-projets en cours</h2><button className="text-link" onClick={()=>navigate({page:'client',id:client.id,tab:'projects'})}>Voir tout<ArrowUpRight size={14}/></button></div>{ps.map(p=><button className="project-brief-row" key={p.id} onClick={()=>{navigate({page:'client',id:client.id,tab:'tasks'});setQuery('')}}><Folder size={17}/>{p.name}<small>{tasks.filter(t=>t.projectId===p.id).length} tâches</small><ChevronRight size={14}/></button>)}{!ps.length&&<button className="btn" onClick={()=>open('project')}><Plus size={15}/>Nouveau sous-projet</button>}</article><aside><h3>INFORMATIONS CLIENT</h3><dl className="properties">{[['Contact',client.contact],['E-mail',client.email],['Secteur',client.sector],['Ville',client.city],['Langue',client.language],['Contenus vendus / mois',client.quota||'—'],['Accès portail',members.filter(m=>m.role==='client'&&m.clientId===client.id).map(memberName).join(', ')||'Aucun · inviter depuis Équipe'],['Créé le',dateLabel(client.createdAt.slice(0,10))]].map(([l,v])=><div key={l}><dt>{l}</dt><dd>{v||'—'}</dd></div>)}</dl><div className="aside-actions"><button className="btn" onClick={()=>navigate({page:'portal',id:client.id,tab:'home'})}><Eye size={16}/>Aperçu du portail client<ArrowUpRight size={15}/></button><button className="btn" onClick={()=>navigate({page:'annex',id:client.id})}><FileSignature size={16}/>Annexe contractuelle</button><button className="btn ghost" onClick={()=>open('archive',client)}><Archive size={16}/>{client.archived?'Restaurer le client':'Archiver le client'}</button></div></aside></div>:tab==='projects'?<><div className="section-head"><h2>{ps.length} sous-projets</h2><button className="btn primary" onClick={()=>open('project')}><Plus size={16}/>Nouveau sous-projet</button></div>{ps.map(p=>{const ts=tasks.filter(t=>t.projectId===p.id),done=ts.filter(t=>t.status==='Validé').length;return <div className="project-row" key={p.id}><span className="client-mark"><Folder size={20}/></span><button onClick={()=>open('project',p)}><strong>{p.name}</strong><small>{p.description||'Ajouter une description'}</small></button><span>{ts.length} tâches</span><div className="project-progress"><Progress value={ts.length?done/ts.length*100:0}/><small>{done}/{ts.length} validées</small></div><button className="icon-button" aria-label={`Archiver ${p.name}`} onClick={()=>open('archive',p)}><Archive size={16}/></button></div>})}{!ps.length&&<Blank title="Le premier sous-projet vous attend" text="Un sous-projet regroupe les tâches d’une même mission."/>}<details className="archived-projects"><summary>Sous-projets archivés ({projects.filter(p=>p.clientId===client.id&&p.archived).length})</summary>{projects.filter(p=>p.clientId===client.id&&p.archived).map(p=><div className="link-row" key={p.id}>{p.name}<button className="btn" onClick={()=>open('archive',p)}>Restaurer</button></div>)}</details></>:tab==='tasks'?TaskDatabase():<><div className="section-head"><h2>Plan éditorial</h2><button className="btn primary" onClick={()=>open('task')}><Plus size={16}/>Nouveau contenu</button></div><Calendar editorial items={tasks.filter(t=>t.clientId===client.id)}/></>}</>}
 function Comments(){return <section className="comments"><h2>Commentaires</h2>{records.filter(r=>r.kind==='comment'&&r.taskId===task?.id).sort((a,b)=>a.createdAt.localeCompare(b.createdAt)).map(c=><div className="comment" key={c.id}><Avatar name={c.author}/><div><strong>{c.author}</strong><small>{timeLabel(c.createdAt)}</small><p>{c.name}</p></div></div>)}{!records.some(r=>r.kind==='comment'&&r.taskId===task?.id)&&<p className="small-note">La conversation commence ici.</p>}<form className="comment-composer" onSubmit={addComment}><Avatar name={user.name} image={user.image}/><label className="sr-only" htmlFor="comment">Écrire un commentaire</label><textarea id="comment" maxLength={5000} value={comment} onChange={e=>setComment(e.target.value)} placeholder="Écrire un commentaire…" rows={2}/><button className="btn" disabled={busy||!comment.trim()||!!task&&archived(task)} aria-label="Envoyer le commentaire"><Send size={16}/></button></form></section>}
 function TaskPage(){if(!task)return <Blank title="Tâche introuvable"/>;return <><button className="text-link back" onClick={()=>navigate({page:'tasks'})}><ArrowLeft size={15}/>Toutes les tâches</button><Heading emoji="📝" title={task.name} subtitle={`${cname(task.clientId)} / ${pname(task.projectId)}`} action={<div className="inline"><button className="btn" onClick={()=>open('archive',task)}><Archive size={15}/>{task.archived?'Restaurer':'Archiver'}</button><button className="btn" disabled={archived(task)} onClick={()=>open('task',task)}>Modifier</button>{task.status!=='À valider'&&task.status!=='Validé'&&<button disabled={busy||archived(task)} className="btn primary" onClick={()=>update(task,{status:'À valider'},`Envoyé au client · validation tacite dans ${flow.validationHours} h`)}><Send size={15}/>Envoyer au client</button>}{task.status==='Validé'&&!task.publishedAt&&!task.evergreen&&<button disabled={busy||archived(task)} className="btn primary" onClick={()=>act({action:'publish',taskId:task.id},'Contenu marqué publié')}><Megaphone size={15}/>Marquer publié</button>}</div>}/><div className="task-state"><Chip status={task.status}/><CourtChip task={task}/>{task.publishedAt&&<span className="flag-pill ok"><Megaphone size={11}/>Publié le {timeLabel(task.publishedAt)}</span>}{task.evergreen&&<span className="flag-pill"><Sparkles size={11}/>Réserve evergreen</span>}{task.request&&<span className="flag-pill"><Inbox size={11}/>Demande portail · {task.request.by}</span>}{revisionState(task).overBudget&&<span className="flag-pill warn">Hors forfait · tour {revisionState(task).used}</span>}{task.lockOverride&&<span className="flag-pill"><Unlock size={11}/>Verrou J−{flow.lockDays} levé</span>}{archived(task)&&<span className="small-note">Archivée · restaurez les éléments parents avant de reprendre le travail.</span>}{task.status==='À valider'&&<span className="small-note"><Clock size={12}/> Chez le client depuis le {timeLabel(task.sentAt)} · validation tacite dans {Math.max(0,Math.round(hoursLeft(task,new Date())??0))} h ({timeLabel(task.approvalDueAt)})</span>}</div>
{(()=>{const gates=gatesFor(task,today);return gates.length?<div className="gates">{gates.map(g=><div key={g.key} className={g.reached?'reached':g.late?'late':''}><span>{g.reached?<Check size={12}/>:g.late?<X size={12}/>:<Clock size={12}/>}</span><strong>{g.label}</strong><small>J−{flow.gates.find(x=>x.key===g.key)!.offset} · {dateLabel(g.day)}</small></div>)}<div className="gate-publish"><span><Megaphone size={12}/></span><strong>Publication</strong><small>J · {dateLabel(task.due)}{insideLock(task.due,today)&&!task.sentAt?' · dans la fenêtre gelée':''}</small></div></div>:<div className="gates none"><Sparkles size={13}/><span>{task.evergreen?'Contenu de réserve : sans date, prêt à combler un trou du calendrier.':'Sans date de publication — les jalons apparaîtront une fois la date fixée.'}</span>{!task.due&&task.status==='Validé'&&!task.publishedAt&&<button className="btn" disabled={busy||archived(task)} onClick={()=>update(task,{evergreen:!task.evergreen},task.evergreen?'Retiré de la réserve':'Placé dans la réserve evergreen')}><Sparkles size={14}/>{task.evergreen?'Retirer de la réserve':'Mettre en réserve evergreen'}</button>}</div>})()}<div className="workflow">{statuses.map((s,i)=><div key={s} className={i<=statuses.indexOf(task.status!)?'reached':''}><span className={s===task.status?'current':''}>{i<statuses.indexOf(task.status!)?<Check size={14}/>:i+1}</span><strong>{s}</strong></div>)}</div><div className="detail-split"><article><div className="section-head"><h2>Brief</h2></div><p className="document-copy">{task.description||'Aucun brief renseigné.'}</p><div className="section-head second"><h2>Livrable</h2></div><div className="deliverable"><div className="doc-thumb"><FileText size={30}/></div><div><strong>{link(task)?task.demo?'Document de démonstration':'Fichier de livraison':'Aucun livrable'}</strong><small>{task.demo?'Exemple fictif · à remplacer avant utilisation réelle':task.deliverable||'Collez le lien de votre fichier pour le faire valider.'}</small><div className="inline">{link(task)&&<a className="btn" href={link(task)} target="_blank" rel="noopener noreferrer"><ArrowUpRight size={15}/>Ouvrir</a>}<button className="btn" disabled={archived(task)} onClick={()=>open('task',task)}>{link(task)?'Remplacer':'Ajouter un lien'}</button>{task.status==='À valider'&&<button className="btn" onClick={()=>navigate({page:'review',id:task.id})}><Eye size={15}/>Aperçu de la revue</button>}</div></div></div>{Comments()}</article><aside><h3>PROPRIÉTÉS</h3><dl className="properties">{[['Client',cname(task.clientId)],['Sous-projet',pname(task.projectId)],['Assigné',task.assignee||'Non assigné'],['Publication',dateLabel(task.due)],['Source',task.source],['Canal',task.channel||'—'],['Tours de retours',`${revisionState(task).used} / ${flow.maxRevisionRounds}${revisionState(task).overBudget?' · hors forfait':''}`],['Créée le',dateLabel(task.createdAt.slice(0,10))]].map(([l,v])=><div key={l}><dt>{l}</dt><dd>{v}</dd></div>)}<div><dt>Statut</dt><dd><Pick label="Statut de la tâche" value={task.status!} onChange={s=>{if(s)void update(task,{status:s as Status})}} items={[...statuses]}/></dd></div></dl>{task.signOff&&<div className="receipt"><ShieldCheck size={16}/><div><strong>Reçu de validation</strong><small>{task.signOff.mode==='silence'?'Validation tacite — délai écoulé':task.signOff.mode==='studio'?'Validation depuis le studio':'Validation explicite du client'}</small><small>{task.signOff.by}{task.signOff.email?` · ${task.signOff.email}`:''}</small><small>{timeLabel(task.signOff.at)} · {task.signOff.round} tour{task.signOff.round!==1?'s':''} utilisé{task.signOff.round!==1?'s':''}</small></div></div>}<h3 className="history-heading">HISTORIQUE</h3><div className="history">{task.history?.slice().reverse().map((e,i)=><div key={i}><span/><p>{e.text}<small>{timeLabel(e.date)}</small></p></div>)}</div></aside></div></>}
 const modalTitle=modal?.type==='archive'?(modal.record?.archived?'Restaurer cet élément':'Archiver cet élément'):modal?.type==='approve'?'Valider ce livrable':modal?.type==='feedback'?'Demander des modifications':`${modal?.record?'Modifier':'Nouveau'} ${modal?.type==='client'?'client':modal?.type==='project'?'sous-projet':'tâche'}`;
 const routeTitle=route.page==='home'?'Accueil':route.page==='tasks'?'Tâches':route.page==='clients'?'Clients':route.page==='team'?'Équipe':route.page==='flow'?'Pilotage':route.page==='annex'?'Annexe contractuelle':client?.name||task?.name||'Espace';
 if(auth)return <Login/>;
 if(noAccess)return <div className="auth-screen"><div className="auth-form google-login"><img className="auth-logo" src="/the-one-core-logo.svg" alt="The One Core"/><h1>Accès sur invitation<span className="wordmark-dot">.</span></h1><p>Votre compte ({user.email||'connecté'}) n’a pas d’espace attribué. Demandez au studio une invitation — avec Google elle s’applique à votre adresse, avec un mot de passe vous recevrez un code.</p><div className="inline"><button className="btn primary" disabled={busy} onClick={logout}><LogOut size={15}/>Se déconnecter</button><button className="btn" onClick={load}><RefreshCw size={15}/>Réessayer</button></div></div><div className="auth-flow"/></div>;
 if(workspace?.role==='client'){const own=clients.find(c=>c.id===workspace.clientId);if(loading||!own)return <div className="loading portal-loading">{loading?<Skeleton className="h-10 w-48"/>:<Blank title="Accès client indisponible" text={error||'Contactez le studio.'}/>}</div>;const r=route.page==='review'||route.page==='portal'?route:{page:'portal',id:own.id,tab:'home'};return <Portal mode="client" records={records} client={own} user={user} route={r} today={today} busy={busy} error={error} notice={notice} navigate={navigate} mutate={mutate} onNotice={setNotice} onError={setError} onLeave={logout}/>;}
 if(portal&&currentClient)return <Portal mode="preview" records={records} client={currentClient} user={user} route={route} today={today} busy={busy} error={error} notice={notice} navigate={navigate} mutate={mutate} onNotice={setNotice} onError={setError} onLeave={()=>navigate({page:'client',id:currentClient.id})}/>;
 return <SidebarProvider style={{'--sidebar-width':'260px'} as React.CSSProperties}><Sidebar className="tracker-sidebar"><SidebarHeader><div className="brand"><img className="sidebar-logo" src="/the-one-core-logo.svg" alt="The One Core"/></div></SidebarHeader><SidebarContent><><SidebarGroup><SidebarMenu><NavItem icon={Search} label="Rechercher" onClick={()=>setSearchOpen(true)}/><NavItem icon={Plus} label="Nouveau" onClick={()=>open('task')}/></SidebarMenu><span className="keyboard-hint">⌘ K</span></SidebarGroup><SidebarGroup><SidebarGroupLabel>INTERNE</SidebarGroupLabel><SidebarMenu><NavItem icon={Home} label="Accueil" active={route.page==='home'} onClick={()=>navigate({page:'home'})}/><NavItem icon={CheckSquare} label="Tâches" active={route.page==='tasks'||route.page==='task'} badge={tasks.filter(t=>t.status!=='Validé').length} onClick={()=>navigate({page:'tasks'})}/><NavItem icon={Users} label="Clients" active={route.page==='clients'} onClick={()=>navigate({page:'clients'})}/><NavItem icon={Users} label="Équipe" active={route.page==='team'} onClick={()=>navigate({page:'team'})}/><NavItem icon={Gauge} label="Pilotage" active={route.page==='flow'||route.page==='annex'} badge={records.filter(r=>r.kind==='event'&&r.audience!=='client'&&!r.read).length} onClick={()=>navigate({page:'flow'})}/></SidebarMenu></SidebarGroup><SidebarGroup><SidebarGroupLabel>CLIENTS<button className="section-plus" aria-label="Ajouter un client" onClick={()=>open('client')}><Plus size={14}/></button></SidebarGroupLabel><SidebarMenu>{clients.filter(c=>!c.archived).map(c=><NavItem icon={Folder} key={c.id} label={c.name} active={route.page==='client'&&route.id===c.id} onClick={()=>navigate({page:'client',id:c.id})}/>)}</SidebarMenu></SidebarGroup></></SidebarContent><SidebarFooter>{workspaces.length>1?<label className="workspace-switch"><span>Espace</span><select value={workspace?.id||''} onChange={e=>void switchWorkspace(e.target.value)}>{workspaces.map(w=><option key={w.id} value={w.id}>{w.name} · {roleLabels[w.role]}</option>)}</select></label>:<div className="sidebar-caption"><span className="mini-mark">Votre prochain grand projet.</span><small>Tout commence ici.</small></div>}<div className="user-row"><Avatar name={user.name} image={user.image}/><div><strong>{user.name.includes('@')?user.name.split('@')[0]:user.name}</strong><small>{workspace?`${roleLabels[workspace.role]} · espace privé`:'Mode démonstration'}</small></div><button disabled={busy} onClick={logout} aria-label="Se déconnecter"><LogOut size={15}/></button></div></SidebarFooter></Sidebar><main className="workspace"><header className="topbar"><SidebarTrigger aria-label="Afficher le menu"/><span className="workspace-label"><Briefcase size={14}/>Studio workspace</span><ChevronRight size={13}/><span>{routeTitle}</span><div className="grow"/><button className="top-search" onClick={()=>setSearchOpen(true)} aria-label="Rechercher dans le studio"><Search size={16}/><span>Rechercher…</span><kbd>⌘ K</kbd></button>{busy?<span className="save-state"><Loader2 className="spin" size={13}/>Enregistrement…</span>:<span className="save-state"><Lock size={12}/>Privé</span>}<button className="icon-button" aria-label="Actualiser les données" onClick={load}><RefreshCw size={15}/></button></header><div className="page-content">{error&&<div className="error-banner" role="alert"><span>{error}</span><button className="btn" onClick={load}>Actualiser</button><button aria-label="Fermer l’erreur" onClick={()=>setError('')}><X size={16}/></button></div>}{loading?<div className="loading"><Skeleton className="h-10 w-48"/><Skeleton className="h-5 w-80"/>{[1,2,3,4,5].map(i=><Skeleton key={i} className="h-10 w-full"/>)}</div>:route.page==='home'?HomePage():route.page==='tasks'?<><Heading emoji="✅" title="Tâches" subtitle="Organisez les priorités. Faites avancer chaque projet."/>{TaskDatabase()}</>:route.page==='clients'?ClientsPage():route.page==='client'?ClientPage():route.page==='task'?TaskPage():route.page==='team'?<TeamPage workspace={workspace} members={members} clients={clients} currentUserId={user.id} currentUserImage={user.image} busy={busy} onChange={changeMember} onRefresh={load}/>:route.page==='flow'?<FlowPage records={records} today={today} busy={busy} onOpenTask={id=>navigate({page:'task',id})} onOpenClient={id=>navigate({page:'client',id})} onMarkRead={async ids=>{try{await mutate({action:'mark-read',ids})}catch(e){setError((e as Error).message)}}} onRefresh={load}/>:route.page==='annex'?<Annex studio={workspace?.name||'The One Core'} client={client?.name} onBack={()=>navigate(client?{page:'client',id:client.id}:{page:'flow'})}/>:<Blank title="Page introuvable" action={<button className="btn" onClick={()=>navigate({page:'home'})}>Retour à l’accueil</button>}/>} {records.some(r=>r.demo)&&<div className="demo-caption">Les éléments de démonstration sont fictifs. Vous pouvez les modifier ou les archiver.</div>}</div></main>{notice&&<div className="toast" role="status"><CheckCircle2 size={17}/>{notice}</div>}
 <Dialog open={!!modal} onOpenChange={o=>{if(!o&&!busy)setModal(null)}}><DialogContent className="tracker-modal"><DialogHeader><DialogTitle>{modalTitle}</DialogTitle><DialogDescription>{modal?.type==='archive'?'L’historique est conservé. Vous pourrez restaurer cet élément.':modal?.type==='approve'||modal?.type==='feedback'?'Action depuis l’aperçu studio, enregistrée au nom du propriétaire.':'Les modifications sont enregistrées dans votre espace privé.'}</DialogDescription></DialogHeader><form onSubmit={submit}>{modal?.type==='archive'?<p className="confirm-copy">{modal.record?.archived?'Restaurer':'Archiver'} « {modal.record?.name} » ? {modal.record?.kind!=='task'&&!modal.record?.archived?'Ses éléments associés seront masqués des vues actives.':''}</p>:modal?.type==='approve'?<p className="confirm-copy">Confirmer la validation de « {modal.record?.name} » ? Le statut passera à « Validé ».</p>:modal?.type==='feedback'?<label className="form-field"><span>Modifications demandées</span><textarea autoFocus required maxLength={5000} rows={6} value={form.feedback||''} onChange={e=>set('feedback',e.target.value)} placeholder="Précisez ce qui doit être ajusté…"/></label>:<div className="form-fields"><label className="form-field title-field"><span>Nom *</span><input autoFocus required maxLength={160} value={form.name||''} onChange={e=>set('name',e.target.value)} placeholder={modal?.type==='task'?'Nom de la tâche':'Nom'}/></label>{modal?.type!=='client'&&<label className="form-field"><span>Client *</span><Pick label="Client" value={form.clientId||''} onChange={v=>set('clientId',v)} items={clients.filter(c=>!c.archived).map(c=>({value:c.id,label:c.name}))}/></label>}{modal?.type==='task'&&<><label className="form-field"><span>Sous-projet *</span><Pick label="Sous-projet" value={form.projectId||''} onChange={v=>set('projectId',v)} items={projects.filter(p=>p.clientId===form.clientId&&!p.archived).map(p=>({value:p.id,label:p.name}))}/>{!projects.some(p=>p.clientId===form.clientId&&!p.archived)&&<small>Créez un sous-projet depuis la fiche client avant d’ajouter une tâche.</small>}</label><div className="form-pair"><label className="form-field"><span>Assigné</span><Pick label="Assigné" emptyLabel="Non assigné" value={form.assignee||''} onChange={v=>set('assignee',v)} items={[...new Set([...members.map(memberName),...(form.assignee?[form.assignee]:[])])].map(value=>({value,label:value}))}/></label><label className="form-field"><span>Échéance</span><DatePicker label="Échéance" value={form.due||''} onChange={value=>set('due',value)}/></label></div><div className="form-pair"><label className="form-field"><span>Source / lien de brief</span><input type="url" maxLength={2000} value={form.source||''} onChange={e=>set('source',e.target.value)} placeholder="https://drive.google.com/..."/><small>Collez le lien du brief, du message ou de la demande client.</small></label><label className="form-field"><span>Statut</span><Pick label="Statut" value={form.status||'À faire'} onChange={v=>set('status',v||'À faire')} items={[...statuses]}/></label></div><label className="form-field"><span>Livrable</span><input type="url" maxLength={2000} value={form.deliverable||''} onChange={e=>set('deliverable',e.target.value)} placeholder={modal.record?.demo?'Lien d’exemple conservé si vide':'https://…'}/></label><label className="form-check"><input type="checkbox" checked={form.evergreen==='true'} onChange={e=>set('evergreen',e.target.checked?'true':'')}/><span><strong>Réserve evergreen</strong><small>Contenu sans date, validé à l’avance pour combler un trou du calendrier.</small></span></label>{form.due&&insideLock(form.due,today)&&form.due!==modal.record?.due&&<p className="lock-note"><Lock size={13}/>Verrou J−{flow.lockDays} : cette date tombe dans la semaine gelée. {canManageMembers(workspace?.role||'viewer')?'Vous pourrez lever le verrou à l’enregistrement.':'Un administrateur devra lever le verrou.'}</p>}</>}{modal?.type==='client'&&<><div className="form-pair"><label className="form-field"><span>Secteur</span><input value={form.sector||''} onChange={e=>set('sector',e.target.value)}/></label><label className="form-field"><span>Ville</span><input value={form.city||''} onChange={e=>set('city',e.target.value)}/></label></div><div className="form-pair"><label className="form-field"><span>Contact principal</span><input value={form.contact||''} onChange={e=>set('contact',e.target.value)}/></label><label className="form-field"><span>E-mail</span><input type="email" value={form.email||''} onChange={e=>set('email',e.target.value)}/></label></div><div className="form-pair"><label className="form-field"><span>Contenus vendus / mois</span><input inputMode="numeric" pattern="[0-9]*" maxLength={3} value={form.quota||''} onChange={e=>set('quota',e.target.value.replace(/\D/g,''))} placeholder="ex. 12"/><small>Sert au ratio « livré vs vendu » du pilotage.</small></label><label className="form-field"><span>Langue du portail</span><Pick label="Langue" value={form.language||'Français'} onChange={v=>set('language',v||'Français')} items={['Français','العربية']}/></label></div><label className="form-field"><span>Dossier partagé</span><input type="url" value={form.drive||''} onChange={e=>set('drive',e.target.value)} placeholder="https://…"/></label><label className="form-field"><span>Lien du contrat</span><input type="url" value={form.contract||''} onChange={e=>set('contract',e.target.value)} placeholder="https://…"/></label></>}<label className="form-field"><span>{modal?.type==='client'?'Brief':'Description'}</span><textarea rows={4} maxLength={15000} value={form.description||''} onChange={e=>set('description',e.target.value)} placeholder="Objectifs, références et consignes…"/></label>{modal?.type==='task'&&<details><summary>Publication sur les réseaux sociaux</summary><div className="form-pair"><label className="form-field"><span>Canal</span><Pick label="Canal de publication" value={form.channel||''} onChange={v=>set('channel',v)} items={[...channels]}/></label><label className="form-field"><span>Heure</span><input type="time" value={form.time||''} onChange={e=>set('time',e.target.value)}/></label></div><small>L’échéance sert de date de publication. Aucune publication automatique.</small></details>}</div>}{formError&&<p role="alert" className="form-error">{formError}</p>}<DialogFooter className="modal-footer"><button type="button" className="btn" disabled={busy} onClick={()=>setModal(null)}>Annuler</button><button className="btn primary" disabled={busy}>{busy?<><Loader2 size={15} className="spin"/>Enregistrement…</>:modal?.type==='archive'?(modal.record?.archived?'Restaurer':'Archiver'):modal?.type==='approve'?'Confirmer la validation':modal?.type==='feedback'?'Enregistrer les retours':modal?.record?'Enregistrer':modal?.type==='task'?'Créer la tâche':'Créer'}</button></DialogFooter></form></DialogContent></Dialog>
 <Dialog open={searchOpen} onOpenChange={setSearchOpen}><DialogContent className="tracker-modal search-modal"><DialogHeader><DialogTitle>Rechercher dans l’espace</DialogTitle><DialogDescription>Clients, sous-projets et tâches.</DialogDescription></DialogHeader><label className="search-input"><Search size={18}/><input autoFocus value={globalQuery} onChange={e=>setGlobalQuery(e.target.value)} placeholder="Nom d’une tâche, d’un client…" aria-label="Recherche globale"/></label><div className="search-results">{records.filter(r=>['client','task','project'].includes(r.kind)&&!archived(r)&&r.name.toLowerCase().includes(globalQuery.toLowerCase())).slice(0,15).map(r=><button key={r.id} onClick={()=>{navigate({page:r.kind==='task'?'task':'client',id:r.kind==='project'?r.clientId:r.id,tab:r.kind==='project'?'projects':undefined});setSearchOpen(false)}}>{r.kind==='task'?<FileText size={16}/>:<Folder size={16}/>}<span>{r.name}<small>{r.kind==='task'?'Tâche':r.kind==='project'?'Sous-projet':'Client'}</small></span><ChevronRight size={16}/></button>)}{!records.some(r=>['client','task','project'].includes(r.kind)&&!archived(r)&&r.name.toLowerCase().includes(globalQuery.toLowerCase()))&&<p>Aucun résultat.</p>}</div></DialogContent></Dialog>
<Dialog open={!!lockPrompt} onOpenChange={o=>{if(!o&&!busy)setLockPrompt(null)}}><DialogContent className="tracker-modal"><DialogHeader><DialogTitle>Lever le verrou J−{flow.lockDays} ?</DialogTitle><DialogDescription>Le calendrier est gelé {flow.lockDays} jours avant chaque publication. Lever le verrou pour « {lockPrompt?.data?.name} » ({lockPrompt?.data?.due}) sera inscrit dans l’historique.</DialogDescription></DialogHeader><DialogFooter className="modal-footer"><button type="button" className="btn" disabled={busy} onClick={()=>setLockPrompt(null)}>Annuler</button><button className="btn primary" disabled={busy} onClick={async()=>{try{const r=await mutate({...lockPrompt,lockOverride:true});setLockPrompt(null);setModal(null);setDraft(null);setDraftError('');setFormError('');setNotice(`Verrou levé · ${lockPrompt.action==='create'?'contenu créé':'modification enregistrée'}`);if(lockPrompt.action==='create'&&r?.id)navigate({page:'task',id:r.id})}catch(e){setError((e as Error).message)}}}><Unlock size={15}/>Lever le verrou</button></DialogFooter></DialogContent></Dialog></SidebarProvider>
